"Последний импорт:",
"Последние",
"Работодатель выплатит Работнику зарплату, компенсации и другие выплаты по день прекращения включительно не позднее {0} дней со дня прекращения ({1}), а также возмещение ущерба за {2}неиспользованный ежегодный отпуск ({3}). Выходное пособие {4}. До дня прекращения Работник вернёт средства труда, оборудование, ключи и документацию; Работодатель возвращает трудовую книжку в день прекращения ({5}).",
"Работодатель принимает план использования ежегодных отпусков на календарный год не позднее {0} текущего года ({1}) после предварительной консультации с сотрудниками (пожелания подаются до 31.03.) и с учётом потребностей рабочего процесса (сезон, инвентаризация, число сотрудников в объекте). На основании плана принимается решение об использовании отпуска, которое вручается сотруднику не позднее чем за {2} дней до начала использования ({3}); более короткий срок — только с согласия сотрудника и Работодателя. Срок может быть изменён по потребностям рабочего процесса не позднее чем за {4} рабочих дней до начала и с согласия сотрудника, а без согласия — только в случае форс-мажора ({5}); Работодатель в таком случае возмещает фактические расходы, понесённые сотрудником в связи с этим.",
"Работодатель обязан обеспечить Работнику условия труда и меры охраны и безопасности труда, обучить его безопасной работе до начала работы и обеспечить средства и оборудование для работы ({0} и Закон об охране и безопасности труда). Работник обязан соблюдать предписанные меры защиты, гигиенические и санитарные нормы при обороте продуктов питания, использовать средства защиты, беречь имущество и товар Работодателя и немедленно уведомлять непосредственного руководителя о любой опасности, неисправности или ущербе.",
"До начала работы Работодатель письменно ознакомил Работника с правами, обязанностями и ответственностью, связанными с запретом травли (моббинга) на работе, и с посредником по защите от травли ({0}). Работодатель обязан зарегистрировать Работника в обязательном социальном страховании со дня начала работы, подать заявление в течение {1} дней и вручить копию Работнику в течение {2} дней ({3}). Работник обязан сообщить Работодателю об изменении адреса места жительства и электронного адреса в течение {4} дней ({5}) и согласен с тем, что акты могут вручаться также на его электронный адрес ({6}).",
"Работодатель ведёт учёт использования отпусков и отсутствий в бухгалтерской программе (по сотруднику и году: полагается, использовано, осталось), который является основой для решений, расчёта зарплаты и компенсации при прекращении трудовых отношений. По вопросам, не урегулированным настоящими Правилами, применяется {0}; если обязательный для Работодателя коллективный договор устанавливает более благоприятные права, применяются они. Правила публикуются на доске объявлений и вступают в силу на восьмой день со дня публикации.",
"Работодателя представляет и его работой руководит исполнительный директор, который является начальником всех сотрудников. Работой организационной единицы «Розница» и объектов руководит менеджер розницы; в объекте в отсутствие менеджера работу координирует сотрудник, назначенный менеджером (старший смены), без изменения должности. За свою работу сотрудники отвечают перед непосредственным руководителем, определённым настоящими Правилами (графа «Подчиняется»), а руководители — за работу возглавляемой ими единицы. В отсутствие исполнительного директора его замещает лицо, которое он уполномочит письменно.",
"Обязанности по должности определяются трудовым договором до дополнения настоящих Правил.",
"Работа организуется так, чтобы обеспечить законную, эффективную и экономичную деятельность, полное использование рабочего времени, чёткую ответственность каждого сотрудника и равные возможности при приёме на работу и продвижении, без дискриминации по какому-либо признаку. Для должностей устанавливаются только те условия, которые действительно необходимы для выполнения обязанностей.",
"Корпоративная карта",
