"Коммерческой тайной Работодателя, определённой общим актом в соответствии с {0}, считаются данные о закупочных ценах и условиях с поставщиками, обороте и выручке, запасах, бизнес-планах, данные о покупателях и работниках и меры безопасности в объектах. Работник обязан хранить их в тайне в течение трудовых отношений и {1} лет после их прекращения; разглашение коммерческой тайны является основанием для расторжения трудового договора ({2}). Личные данные Работника обрабатываются только в целях реализации прав и обязанностей из трудовых отношений; Работник письменно уведомлён о видеонаблюдении в объектах в целях безопасности людей и имущества.",
"Заведующий в Менеджере подтверждает приёмку товара по калькуляции («в порядке» или расхождение по товару). Калькуляция автоматически не меняется; расхождение решает бухгалтер (возврат, кредит-нота, исправление). Нажмите на строку: подробности и калькуляция.",
