"Производство не найдено.",
"Процедура по закону (",
"Производство начинает исполнительный директор по факту узнавания либо по инициативе любого сотрудника, письменным предупреждением сотруднику в течение {0} дней со дня, когда стало известно о нарушении. Предупреждение содержит личные данные и должность сотрудника, описание и временные рамки нарушения, доказательства и указание на право на устное объяснение. Сотрудник даёт письменное объяснение в течение {1} дней со дня вручения (молчание считается согласием с изложенным), а в течение {2} дней может потребовать устного объяснения; слушание проводится в течение 15 дней со дня вручения предупреждения, с правом сотрудника на присутствие представителя профсоюза и защитника, и ведётся протокол ({3}). Решение — о прекращении производства, освобождении или мере — принимает исполнительный директор в течение {4} дней со дня истечения срока для объяснения либо слушания (30 дней при осмотре или экспертизе); решение содержит вводную часть, резолютивную часть, обоснование и разъяснение о правовой защите, является окончательным и вручается в течение {5} дней. Сотрудник может обжаловать его в течение {6} дней в Агентстве по мирному разрешению трудовых споров, а при прекращении и условном прекращении трудовых отношений — и в суде ({7}).",
"Производство может быть начато в течение {0} месяцев со дня, когда стало известно о нарушении и нарушителе, и должно быть завершено в течение {1} месяцев со дня начала; если нарушение имеет признаки уголовного преступления, начать его можно в течение 6 месяцев со дня, когда о нём стало известно ({2}). Мера не может быть исполнена, если со дня вступления решения в силу прошло {3} дней, а исполнение не начато; предупреждение, денежный штраф и условное прекращение трудовых отношений удаляются из учёта, если в течение {4} лет сотрудник не совершит нового нарушения ({5}). Денежный штраф удерживается из зарплаты по окончательному решению, так чтобы общие удержания без согласия сотрудника не превышали одной трети зарплаты ({6}).",
