"Правилник 34/12, ст. 11: изменение цены товара на складе записывается на основании отчёта о проведённой инвентаризации (переоценка).",
"Правила 34/12 ст. 11: изменение цены товара вносится в учёт торговли на основании отчёта о проведённой инвентаризации. Увеличение вносится как дебет, уменьшение — красным сторно (гр. 4). Новая цена действует со дня переоценки в складских остатках и прайс-листе кассы; история цен сохраняется (Закон о защите потребителей ст. 15).",
"Правилник 34/12 ст. 3 п. 1: учёт ведётся отдельно для каждой точки оптовой торговли и магазина. Опт: учёт EV, счета 1320/1329, 5012, 6020. Розница: учёт EM, счета 134000/134001/134002, 5013, 6021. Вид можно менять, только пока у объекта нет документов.",
"Правилник 34/12 ст. 3: учёт торговли ведётся отдельно для каждой торговой точки. Отправитель: кол. 4 красное сторно по своей продажной стоимости; получатель: кол. 4 дебетование по внутренней калькуляции. PPZPDV ст. 80: внутренние счета не влияют на налоговое обязательство.",
"Правилник 34/12, ст. 7, графа 4: приход «для оптовой торговли по оптовым ценам». Нормативный акт прямо не определяет, включает ли оптовая цена НДС; применена цена без НДС (та же сумма, что и на счёте 1320). Подтверждается бухгалтером.",
