"Ни один нормативный акт не упоминает расписку о выдаче. Толкование, более близкое к тексту ZPDV ст. 4 п. 1 (оборот — это передача права распоряжения): товар по расписке не продан и остаётся имуществом компании; он списывается только чеком (Правилник 34/12 ст. 7 кол. 5), а возврат не отражается в торговой книге. Склад: расход на день выдачи, приход на день возврата. Другое толкование: если получатель распоряжается товаром, поставка совершена (НДС не позднее 8 дней с передачи, ZPDV ст. 18 п. 3). Товар по расписке инвентаризируется по отдельной инвентаризационной ведомости (Правилник об инвентаризации, ст. 2).",
