"Закрыть торговую книгу за {0} год (все объекты)?\\n\\nКнига сохраняется в PDF с отпечатком, создаётся «первая и последняя страница для заверения», а изменение этого года потребует отмены закрытия.{1}",
"Закрытие книги и создание PDF…",
"Главный компьютер компании забирает закрытия касс автоматически, в каждом цикле синхронизации.",
"Закрывающая проводка на 31.12.: доходы (класс 6) и расходы (класс 5) переносятся через 699/599 на 710, результат на 720, налог на прибыль 721/4810, а чистая прибыль на 3410 (убыток на 3510). Открытие следующего года переносит сальдо классов 0–4 в начальный остаток на 01.01. Перед закрытием: все месяцы проведены, инвентаризация и амортизация проведены, декларация PD сохранена (она даёт точный налог).",
