"Закон о бухгалтерском учёте и Закон о налоге на прибыль — до 31.03.",
"Закон о бухгалтерском учёте не требует последовательности номеров без пропусков, а требует достоверных документов и хронологической последовательности записей (ст. 10 и 13). Для пропущенных номеров достаточно примечания — оно печатается под книгой покупок (Excel и PDF) за этот год.",
"Закон о труде («Официальный вестник Черногории», №№ 74/19, 8/21, 59/21, 68/21, 145/21, 77/24, 84/24, 86/24, 122/25, 165/25, 51/26 и 103/26)",
"Закон о труде не устанавливает процент надбавки за стаж (ст. 98 — «в соответствии с коллективным договором и трудовым договором»). Генеральный коллективный договор (ст. 14) как минимум до 30.04.2026 обязывал применять разряды: 0,5 % до 10 лет, 0,75 % от 10 до 20, 1 % свыше 20 лет стажа (обычное толкование — кумулятивно: 15 лет = 10 × 0,5 + 5 × 0,75 = 8,75 %). Стаж = полные годы общего трудового стажа на первый день расчётного месяца. Схема действует с указанной даты до следующей; до первой действует «ровно». Та же схема (теми же словами) вносится в трудовой договор. Закрытые расчёты не изменяются — разницу по ним даёт отчёт «Разница надбавки за стаж».",
"Закон о социальной защите и защите детей — заявление в течение 30 дней с начала отсутствия",
"Закон о внутренней торговле, ст. 35b: розничная торговля не осуществляется по воскресеньям, а также в государственные и другие праздничные дни. Исключения, среди прочих, составляют специализированные магазины или киоски по продаже хлеба, хлебобулочных изделий и тортов, цветов, сувениров, прессы, средств защиты растений или похоронных принадлежностей (п. 3 пп. 2), киоски в закрытых зонах вокзалов, аэропортов и портов (пп. 6) и киоски во время мероприятий, фестивалей и других событий (пп. 7). Специализированная торговля — это «продажа преимущественно одного вида товара» (п. 4). Штраф для юридического лица составляет 1.000–10.000 € (ст. 43) плюс закрытие объекта (ст. 42 п. 3). Киоск является отдельной точкой продаж (ст. 15 п. 2): отдельное торговое помещение, зарегистрированное в Налоговой администрации, со своим учётом торговли.",
