"Зарплата выплачивается в денежной форме, на текущий счёт Работника {0}{1}, один раз в месяц, не позднее {2} числа месяца за предыдущий месяц, с письменным расчётом зарплаты ({3}). Работник имеет право на возмещение расходов на командировки и другие выплаты в соответствии с законом и общим актом Работодателя. Работник имеет право раскрывать данные о собственной зарплате для реализации права на равную оплату труда ({4}).",
